def compute_a(N):
    a = {}
    for n in range(1, N + 1):
        if n == 1 or n == 2:
            a[n] = 1
        else:
            # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
            a_n_minus_1 = a[n-1]

            # Check if a_{n-1} and n - a_{n-1} are in the map (they should be if n > 2)
            if a_n_minus_1 not in a:
                # This should not happen if the sequence is well-defined for positive integers
                raise IndexError(f"Index {a_n_minus_1} required but not calculated.")

            if n - a_n_minus_1 <= 0:
                 # This should not happen based on the problem constraints (a_n are positive integers)
                 raise ValueError("Non-positive index encountered.")

            # Both a_{a_{n-1}} and a_{n - a_{n-1}} must be defined
            if a[a_n_minus_1] is None or a[n - a_n_minus_1] is None:
                 raise IndexError("Required terms not computed.")

            a[n] = a[a_n_minus_1] + a[n - a_n_minus_1]

    return a

